          for (const auto &LI : Labels) {
            SourceLocation L = LI.Loc;
            if (SM.isBeforeInTranslationUnit(L, Loc)) {
              if (!Best ||
                  SM.isBeforeInTranslationUnit(BestLoc, L)) {
