              const Expr *LHS = BO->getLHS()->IgnoreParenImpCasts();
              const Expr *RHS = BO->getRHS()->IgnoreParenImpCasts();
              const DeclRefExpr *LDRE = dyn_cast<DeclRefExpr>(LHS);
              const VarDecl *VD = LDRE ? dyn_cast<VarDecl>(LDRE->getDecl()) : nullptr;

