  using SiteList = llvm::SmallVector<const Stmt *, 4>;
  std::map<std::string, SiteList> LocalRMWSites;     // from this_cpu_ptr
  std::map<std::string, SiteList> RemoteWriteSites;  // from per_cpu_ptr

